import {architectures,architectureGroups,architectureRelations,architectureModels,architectureSources,architectureUpdated} from './data/architectures.js';
import {architectureLessons} from './data/architecture-lessons.js';
import {architectureExercises} from './data/architecture-practice.js';
import {architectureBudget,causalSelection,deltaStep,scalarSSM} from './architecture-lab.js';
import {workshops} from './data/workshops.js';
import {escapeHTML as e} from './state.js';

const term=id=>architectures.find(x=>x.id===id);
const group=id=>architectureGroups.find(x=>x.id===id);
const link=id=>`<a class="arch-node" href="#/architectures/catalog/${id}">${e(term(id)?.name||id)}</a>`;
const sourceList=keys=>`<div class="arch-sources">${[...new Set(keys)].map(key=>{const s=architectureSources[key];return `<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`;}).join('')}</div>`;
const projects=ids=>ids.map(id=>{const w=workshops.find(x=>x.id===id);return `<a class="btn btn-small" href="#/projects/workshop-${id}">${e(w.number)} · ${e(w.title)} →</a>`;}).join('');
const codes=ids=>ids.map(id=>`<a class="btn btn-small" href="#/code/${id}">${e(architectureExercises.find(x=>x.id===id).title)} →</a>`).join('');
let search='',category='all',compare=['kda','dsa','swa'];
const tabs=[['learn','从这里学'],['map','结构关系图'],['catalog','分类目录'],['compare','并排比较'],['models','模型拆解'],['lab','动手实验']];
const progress=(l,state)=>l.checks.filter((q,i)=>state.architectureChecks?.[`${l.id}:${i}`]===q.answer).length;

export function architecturePage(id='',state={}){
 const [raw,selected]=id.split('/'),tab=tabs.some(t=>t[0]===raw)?raw:'learn';
 const content=tab==='learn'?(selected?lessonPage(selected,state):learningHome(state)):tab==='map'?mapPage():tab==='catalog'?catalogPage(selected):tab==='compare'?comparePage():tab==='models'?modelsPage():labPage();
 return `<div class="arch-page"><div class="page-heading"><div><span class="eyebrow">MODEL ARCHITECTURE ATLAS</span><h1>把结构放进同一张地图。</h1><p>先知道它解决什么问题，再看怎么计算、怎样组合，以及该用什么实验验证。</p></div></div><nav class="arch-tabs" aria-label="模型结构视图">${tabs.map(([key,title])=>`<a href="#/architectures/${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${title}</a>`).join('')}</nav>${content}<footer class="arch-footer">资料核对：${architectureUpdated} · ${architectureGroups.length} 个分类 · ${architectures.length} 项结构与相关机制。按公开结构族去重，不按模型尺寸重复列项；闭源内部结构不推测。目录是可扩展的研究快照，新方案不代表已经成为行业标准。</footer></div>`;
}
function learningHome(state){
 return `<section class="panel panel-pad arch-intro"><span class="eyebrow">先学骨架，再看变体</span><h2>不是背缩写，而是会做设计选择。</h2><p>结构决定：信息能看见谁、记忆存在哪里、每次调用哪些参数、怎样把视觉与动作接起来。先学下面第 01–03 课，再进入 SSM 与 KDA；看到新名字时，用关系图和目录定位。</p><div class="arch-three"><div><b>第一遍 · 建立全景</b><p>读目标与推演，做课内判断题。每课约 45 分钟，可分两次完成；点击答案会解释原因。</p></div><div><b>第二遍 · 实现机制</b><p>7 道 Python 题在浏览器真实执行，带接口、样例、提示和边界检查。代码与提交记录保存在本机。</p></div><div><b>第三遍 · 训练与对照</b><p>回到 P01/P07/P09/P10，沿数据、loss、训练、评测迭代。目录覆盖广，核心路线深入做；扩展专题按需加入 12 周计划。</p></div></div><a class="btn btn-primary" href="#/architectures/learn/foundation">开始：结构到底决定什么？ →</a></section><div class="arch-lesson-grid">${architectureLessons.map(l=>`<a class="panel panel-pad arch-lesson-card" href="#/architectures/learn/${l.id}"><span class="badge">${l.minutes} 分钟讲解与检查${l.code.length?' · 另有编程练习':''}</span><h2>${e(l.title)}</h2><p>${e(l.goal)}</p><span class="small muted">理解检查 ${progress(l,state)}/${l.checks.length} · ${l.terms.length} 个关联机制</span><b class="arch-go">开始学习 →</b></a>`).join('')}</div><section class="panel panel-pad"><h2>广泛学习，怎样避免浅尝辄止？</h2><p>优先亲手实现因果 mask、KV 预算、SSM 状态和 KDA 更新，然后做窗口/全局/状态/混合的训练对照。低秩近似、递归深度、较新的压缩注意力作为扩展：先能归类和读懂接口，再按任务复现。每个项目保留失败样例和预算表，阅读量不替代实验能力。</p><div class="row wrap">${projects(['memory','systems','omnifm'])}</div></section>`;
}
function lessonPage(id,state){
 const l=architectureLessons.find(x=>x.id===id);if(!l)return missing();
 const index=architectureLessons.indexOf(l),next=architectureLessons[index+1];
 return `<a class="text-link" href="#/architectures/learn">← 返回学习顺序</a><div class="arch-reading-layout"><article class="panel panel-pad arch-reading"><span class="eyebrow">结构导学 · ${l.minutes} 分钟，可分次完成</span><h2>${e(l.title)}</h2><p class="lead">学完要做到：${e(l.goal)}</p><p class="small muted">建议顺序：读一节 → 手算推演 → 回答检查 → 运行代码 → 回到项目。遇到不懂的名称可点右侧目录，随后返回继续。</p>${l.sections.map((s,i)=>`<section id="arch-section-${i}"><span class="eyebrow">STEP ${i+1}</span><h3>${e(s.title)}</h3>${s.body.map(p=>`<p>${e(p)}</p>`).join('')}</section>`).join('')}<section class="arch-worked"><h3>一起推演：${e(l.worked.title)}</h3><ol>${l.worked.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><p><b>得到什么结论：</b>${e(l.worked.result)}</p></section><section><h3>现在检查理解</h3><p>题目只检查本课已经解释的机制。答错会给出原因，可以重新选择；正确数保存在学习备份中。</p>${l.checks.map((q,i)=>{const key=`${l.id}:${i}`,selected=state.architectureChecks?.[key];return `<fieldset class="arch-check" data-check="${key}"><legend>${i+1}. ${e(q.prompt)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="arch-${key}" value="${j}" ${selected===j?'checked':''}> ${e(o)}</label>`).join('')}<div class="arch-feedback" role="status">${Number.isInteger(selected)?feedback(q,selected):'先作答，再查看解析。'}</div></fieldset>`;}).join('')}</section>${l.code.length?`<section><h3>把机制写成可运行的代码</h3><p>每题约 35 分钟，先实现再提交。检查通过后，修改输入并解释边界；不要只复制参考解法。</p><div class="row wrap">${codes(l.code)}</div></section>`:''}<section><h3>带着本课知识回到完整项目</h3><div class="row wrap">${projects(l.projects)}</div></section><section><h3>原始资料 · 用于核对和继续深入</h3>${sourceList(l.sources)}</section><div class="between wrap"><a class="btn" href="#/architectures/lab">打开交互实验</a>${next?`<a class="btn btn-primary" href="#/architectures/learn/${next.id}">下一课 →</a>`:''}</div></article><aside class="arch-aside panel panel-pad"><h3>本课机制定位</h3><div class="arch-node-list">${l.terms.map(link).join('')}</div><h3>为什么要学这一课</h3><p>${e(l.goal)}</p><a class="text-link" href="#/architectures/map">在关系图中看关联 →</a></aside></div>`;
}
const feedback=(q,selected)=>`<b>${selected===q.answer?'✓ 理解正确':'还差一步'}</b><p>${e(q.explanation)}</p>`;
const chains=[
 ['KV 共享程度',['mha','gqa','mqa'],'改变保存表示的共享程度；可见位置可以仍是完整前缀。'],
 ['局部连接与远程通路',['swa','longformer'],'滑窗只保留邻近位置；增加全局连接为长程信息提供额外通路。'],
 ['状态空间路线',['ssm','s4','mamba','mamba2','mamba3'],'家族 → 结构化实现 → 选择性与后续计算设计；不是同一个模型的尺寸升级。'],
 ['纠错写入路线',['linear','deltanet','gdn','kda','gdn2'],'关注如何将信息写进矩阵状态；箭头描述机制变化，不保证性能单调提升。'],
 ['选择与压缩路线',['dsa','csa','csa2'],'从选择读取位置，到序列压缩与版本特定的缓存/索引共享。'],
 ['视觉进入语言或动作',['vit','dino','connector'],'骨干、表示学习与接口处于不同层级；这是组合关系。']
];
function mapPage(){
 return `<section class="panel panel-pad"><h2>先选设计问题，再沿分支探索。</h2><p>这是多轴地图。同一模型可以跨多个分支选组件；连线旁会标注“后续设计”“可组合”等关系，避免误以为所有箭头都是替代或继承。</p><div class="arch-map-root">一个可训练、可推理的模型<br><small>输入 → 表示 → 信息混合 → 输出；目标与更新策略另外定义</small></div><div class="arch-family-grid">${architectureGroups.map(g=>`<a class="arch-family" href="#/architectures/catalog/${architectures.find(x=>x.group===g.id).id}"><span class="eyebrow">${e(g.axis)}</span><h3>${e(g.name)}</h3><p>${e(g.question)}</p><span>${architectures.filter(x=>x.group===g.id).length} 项机制 · 点击展开 →</span></a>`).join('')}</div></section>${chains.map(([title,ids,note])=>`<section class="panel panel-pad"><h2>${title}</h2><p>${note}</p><div class="arch-chain">${ids.map((id,i)=>`${i?`<span class="arch-edge">${e(architectureRelations.find(r=>r.from===ids[i-1]&&r.to===id)?.label||'关联，点击节点查看')} →</span>`:''}${link(id)}`).join('')}</div></section>`).join('')}<section class="panel panel-pad"><h2>不同分支怎样组合？</h2><div class="arch-relation-list">${architectureRelations.filter(r=>r.kind==='可组合'||(r.from==='kda'&&r.to==='dsa')||(r.from==='moe'&&r.to==='dsa')).map(relationRow).join('')}</div><p>点击任意节点可以查看它的所有邻居、作用、代价、练习与原始资料。</p></section>`;
}
const relationRow=r=>`<div class="arch-relation">${link(r.from)}<span><b>${e(r.kind)}</b><small>${e(r.label)}</small></span>${link(r.to)}</div>`;
const matches=()=>architectures.filter(x=>(category==='all'||x.group===category)&&[x.id,x.name,x.purpose,x.mechanism,x.cost].join(' ').toLowerCase().includes(search.trim().toLowerCase()));
function catalogResults(){const items=matches();return `<p class="small muted" role="status">${items.length} / ${architectures.length} 项结果</p><div class="arch-catalog-results">${items.map(x=>`<a href="#/architectures/catalog/${x.id}" class="arch-catalog-card"><span class="badge badge-gray">${e(group(x.group).name)}</span><h3>${e(x.name)}</h3><p>${e(x.purpose)}</p></a>`).join('')||'<p class="arch-empty">没有匹配项。可清除关键词或切换到全部分类。</p>'}</div>`;}
function catalogPage(id){
 const x=term(id);
 return `<section class="panel panel-pad"><h2>按“解决的问题”查结构</h2><div class="arch-search"><label>关键词<input class="field" type="search" id="architecture-search" placeholder="SSM、SWA、KDA、视觉、缓存…" value="${e(search)}"></label><label>分类<select class="field" id="architecture-category"><option value="all">全部分类</option>${architectureGroups.map(g=>`<option value="${g.id}" ${category===g.id?'selected':''}>${e(g.name)}</option>`).join('')}</select></label><button class="btn" id="architecture-clear" type="button">清除筛选</button></div></section>${id&&!x?missing():x?detail(x):''}<section id="architecture-results">${catalogResults()}</section>`;
}
function detail(x){
 const g=group(x.group),relations=architectureRelations.filter(r=>r.from===x.id||r.to===x.id);
 const deep=['deltanet','gdn','kda','gdn2'].includes(x.id)?'delta':g.lesson;
 return `<article class="panel panel-pad arch-detail" id="architecture-detail"><div class="between wrap"><span class="badge">${e(g.name)} · ${e(x.axis)}</span><a class="text-link" href="#/architectures/catalog">回到目录</a></div><h2>${e(x.name)}</h2>${[['为什么需要它',x.purpose],['它怎样计算',x.mechanism],['收益、代价与限制',x.cost],['怎样验证理解',x.experiment]].map(([title,body])=>`<section><h3>${title}</h3><p>${e(body)}</p></section>`).join('')}<div class="row wrap"><a class="btn btn-primary" href="#/architectures/learn/${deep}">从这一族的讲解开始 →</a><a class="btn" href="#/architectures/compare/${x.id}">放入对比表</a></div>${relations.length?`<h3>和其他结构是什么关系？</h3><div class="arch-relation-list">${relations.map(relationRow).join('')}</div>`:''}<h3>对应实战</h3><div class="row wrap">${projects(g.projects)}</div><h3>公开来源</h3>${sourceList(x.sources)}</article>`;
}
function comparePage(){
 return `<section class="panel panel-pad"><h2>先比较改了哪里，再比较好坏。</h2><p>同轴也可能改动不同部位；不同轴往往可以叠加。表格列的是设计取舍，不是未经实验的胜负榜。</p><div class="arch-three">${compare.map((id,i)=>`<label>候选 ${i+1}<select class="field arch-compare-select" data-slot="${i}">${architectures.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${e(x.name)}</option>`).join('')}</select></label>`).join('')}</div><div id="architecture-comparison">${comparison()}</div></section>`;
}
function comparison(){
 const xs=compare.map(term);return `<p class="callout">${new Set(xs.map(x=>x.axis)).size>1?'这些候选处于不同设计轴。先明确各自位置；它们可能组合使用，不能只按一个指标排位。':'这些候选处于同一大类设计轴，但仍需核对保存方式、读取粒度与训练条件；同轴不代表可无训练互换。'}</p><div class="arch-table-scroll"><table class="arch-table"><caption>结构机制与取舍对照</caption><thead><tr><th scope="col">比较维度</th>${xs.map(x=>`<th scope="col">${link(x.id)}</th>`).join('')}</tr></thead><tbody>${[['设计轴','axis'],['解决的问题','purpose'],['具体机制','mechanism'],['代价与限制','cost'],['建议验证','experiment']].map(([label,key])=>`<tr><th scope="row">${label}</th>${xs.map(x=>`<td>${e(x[key])}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">证据</th>${xs.map(x=>`<td>${sourceList(x.sources)}</td>`).join('')}</tr></tbody></table></div><p>下一步：固定数据与训练预算，去 <a href="#/architectures/learn/evaluation">第 11 课</a>设计对照，或先用<a href="#/architectures/lab">预算实验</a>检查成本假设。</p>`;
}
function modelsPage(){
 return `<section class="panel panel-pad"><h2>模型名称是一个组合，不是一个结构。</h2><p>下面按公开版本拆解代表模型。列表展示与学习有关的主要部件，并非完整配置；同一品牌后续版本可能改变设计。未知的闭源内部结构保留未知，不用传闻补齐。</p></section><div class="arch-model-grid">${architectureModels.map(m=>`<article class="panel panel-pad"><h2>${e(m.name)}</h2><p>${e(m.explanation)}</p><div class="arch-chain">${m.parts.map(link).join('<span aria-hidden="true">＋</span>')}</div>${sourceList([m.source])}</article>`).join('')}</div>`;
}
function labPage(){
 return `<section class="panel panel-pad"><h2>实验 A · 缓存与读取预算</h2><p>假设 B=1、32 层、32 个 Q 头、dk=dv=128、KV 为 FP16。MLA 示意潜维 512 + 位置分支 64；矩阵状态用每头 128×128、FP32。各项是替代方案的独立估算，不能相加当成某个真实模型。</p><div class="arch-four"><label>序列长度 T<input class="field arch-budget-input" id="arch-tokens" type="number" min="1" max="65536" value="8192"></label><label>窗口 W（含当前）<input class="field arch-budget-input" id="arch-window" type="number" min="1" max="65536" value="1024"></label><label>每次选择 k<input class="field arch-budget-input" id="arch-topk" type="number" min="1" max="65536" value="512"></label><label>GQA 的 KV 头数<select class="field arch-budget-input" id="arch-heads">${[1,2,4,8,16,32].map(n=>`<option ${n===8?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="arch-budget-output" aria-live="polite"></div><p class="small muted">不含权重、FFN、激活、卷积状态、分配器及索引器额外缓存。滑窗假定所有层均为局部并实际淘汰旧 KV；混合层需逐层另算。位置对不是实际 FLOPs 或速度。DSA 索引仍有稠密位置对，不能把整条路径称为线性。</p><div class="row wrap">${codes(['arch-kv-budget'])}</div></section><section class="panel panel-pad"><h2>实验 B · 全局、滑窗和内容选择看到的历史</h2><p>8 个位置，索引分数固定为 [9,1,8,3,6,2,100,90]。未来分数故意很高；先预测哪些格会被读，再移动 query。这里只展示选择集合，不展示主注意力权重。</p><div class="arch-three"><label>query 位置 <output id="arch-query-label">5</output><input id="arch-query" type="range" min="0" max="7" value="5"></label><label>窗口大小 <output id="arch-mask-window-label">3</output><input id="arch-mask-window" type="range" min="1" max="8" value="3"></label><label>top-k <output id="arch-mask-k-label">3</output><input id="arch-mask-k" type="range" min="1" max="8" value="3"></label></div><div id="arch-mask-output" aria-live="polite"></div><p class="small muted">✓ 可读 · × 不读。每个格展示位置索引，不代表真实模型已经学会选择它。</p><div class="row wrap">${codes(['arch-window-mask','arch-causal-topk','arch-sparse-read'])}</div></section><section class="panel panel-pad"><h2>实验 C · KDA 核心更新逐项展开</h2><p>固定 S=[[2,0],[0,4]]、key=[1,0]、value=[5,1]、query=[1,1]。调节通道遗忘与写入强度，检查“先遗忘 → 读旧预测 → 纠错 → 读新状态”。</p><div class="arch-three">${[['alpha-0','α₀',0.5],['alpha-1','α₁',1],['beta','β',0.5]].map(([id,label,value])=>`<label>${label} <output id="arch-${id}-label">${value}</output><input id="arch-${id}" class="arch-delta-input" type="range" min="0" max="1" step="0.05" value="${value}"></label>`).join('')}</div><div id="arch-delta-output" aria-live="polite"></div><p>这是固定向量上的核心递推，可解释 DeltaNet/GDN/KDA 的差异；不包含完整投影、归一化与训练，也不代表模型性能对比。</p><div class="row wrap">${codes(['arch-gated-delta'])}</div></section><section class="panel panel-pad"><h2>实验 D · SSM 的一阵脉冲</h2><p>h_t=a·h_(t−1)+x_t；初态 0，输入 [1,0,0,0,0,0]。观察遗忘、保持与增长，注意状态变化不等于参数正在训练。</p><label>状态系数 a <output id="arch-ssm-a-label">0.8</output><input id="arch-ssm-a" type="range" min="0" max="1.2" step="0.05" value="0.8"></label><div id="arch-ssm-output" aria-live="polite"></div><div class="row wrap">${codes(['arch-ssm-scan'])}</div></section><section class="panel panel-pad"><h2>完成机制题后，做一次真实训练对照</h2><p>预算与递推正确只是起点。去项目里记录任务质量、训练预算和实测推理表现，再回答“为什么选这个结构”。</p><div class="row wrap">${projects(['memory','systems','omnifm'])}</div></section>`;
}
const missing=()=>'<section class="panel panel-pad"><h2>没有找到这项内容</h2><a href="#/architectures">返回结构学习入口</a></section>';
const number=n=>Number(n.toFixed(4));
const matrix=x=>JSON.stringify(x.map(row=>Array.isArray(row)?row.map(number):number(row)));
export function bindArchitecture(id,state,save){
 const controller=new window.AbortController(),on=(el,type,fn)=>el?.addEventListener(type,fn,{signal:controller.signal});
 const q=sel=>document.querySelector(sel);
 const [tab,selected]=(id||'').split('/');
 if(tab==='compare'&&term(selected)){compare=[selected,...compare.filter(x=>x!==selected)].slice(0,3);while(compare.length<3)compare.push('mha');document.querySelectorAll('.arch-compare-select').forEach((el,i)=>el.value=compare[i]);q('#architecture-comparison').innerHTML=comparison();}
 on(q('#architecture-search'),'input',ev=>{search=ev.target.value;q('#architecture-results').innerHTML=catalogResults();});
 on(q('#architecture-category'),'change',ev=>{category=ev.target.value;q('#architecture-results').innerHTML=catalogResults();});
 on(q('#architecture-clear'),'click',()=>{search='';category='all';q('#architecture-search').value='';q('#architecture-category').value='all';q('#architecture-results').innerHTML=catalogResults();});
 document.querySelectorAll('.arch-compare-select').forEach(el=>on(el,'change',ev=>{compare[Number(ev.target.dataset.slot)]=ev.target.value;q('#architecture-comparison').innerHTML=comparison();}));
 document.querySelectorAll('.arch-check').forEach(el=>on(el,'change',ev=>{
  const key=el.dataset.check,[lesson,index]=key.split(':'),l=architectureLessons.find(x=>x.id===lesson),selected=Number(ev.target.value),check=l?.checks[Number(index)];
  if(!check||!Number.isInteger(selected)||selected<0||selected>=check.options.length)return;
  state.architectureChecks??={};state.architectureChecks[key]=selected;save();el.querySelector('.arch-feedback').innerHTML=feedback(check,selected);
 }));
 function budget(){const out=q('#arch-budget-output');if(!out)return;try{
  const r=architectureBudget({tokens:Number(q('#arch-tokens').value),window:Number(q('#arch-window').value),topk:Number(q('#arch-topk').value),kvHeads:Number(q('#arch-heads').value)});
  out.innerHTML=`<div class="arch-metrics">${[['MHA · 完整 KV',r.mha],['GQA · 完整 KV',r.gqa],['MQA · 完整 KV',r.mqa],['GQA + 全滑窗淘汰',r.swa],['MLA · 示意潜缓存',r.mla],['纯矩阵状态 · FP32',r.state]].map(([label,v])=>`<div><span>${label}</span><strong>${number(v/1024**2)} MiB</strong></div>`).join('')}</div><dl class="arch-pairs"><dt>单头单层：因果全局位置对</dt><dd>${r.densePairs.toLocaleString()}</dd><dt>滑窗位置对</dt><dd>${r.windowPairs.toLocaleString()}</dd><dt>top-k 主读取位置对</dt><dd>${r.sparsePairs.toLocaleString()}</dd><dt>原始 DSA 索引位置对量级</dt><dd>${r.indexPairs.toLocaleString()}（较轻计算，仍需计入）</dd></dl>`;
 }catch(err){out.innerHTML=`<p class="callout" role="alert">${e(err.message)}</p>`;}}
 function mask(){const out=q('#arch-mask-output');if(!out)return;const t=Number(q('#arch-query').value),w=Number(q('#arch-mask-window').value),k=Number(q('#arch-mask-k').value),selected=causalSelection([9,1,8,3,6,2,100,90],t,k);
  for(const [id,value]of [['query',t],['mask-window',w],['mask-k',k]])q(`#arch-${id}-label`).textContent=value;
  out.innerHTML=[['因果全局',i=>i<=t],['SWA',i=>i<=t&&i>=t-w+1],['内容 top-k',i=>selected.includes(i)]].map(([label,fn])=>`<div class="arch-mask-row"><b>${label}</b><div>${Array.from({length:8},(_,i)=>`<span class="arch-cell ${fn(i)?'visible':'masked'}" aria-label="位置 ${i} ${fn(i)?'可读':'不读'}">${i}<small>${fn(i)?'✓':'×'}</small></span>`).join('')}</div></div>`).join('');}
 function delta(){const out=q('#arch-delta-output');if(!out)return;const vals=['alpha-0','alpha-1','beta'].map(id=>{const value=Number(q(`#arch-${id}`).value);q(`#arch-${id}-label`).textContent=value;return value;});const r=deltaStep(vals.slice(0,2),vals[2]);out.innerHTML=`<ol class="arch-calculation">${[['遗忘后的 A',r.decayed],['旧预测 pred',r.prediction],['纠错 error',r.error],['新状态 S_new',r.state],['最终输出 o',r.output]].map(([label,v])=>`<li><b>${label}</b><code>${matrix(v)}</code></li>`).join('')}</ol>`;}
 function ssm(){const out=q('#arch-ssm-output');if(!out)return;const a=Number(q('#arch-ssm-a').value),values=scalarSSM(a);q('#arch-ssm-a-label').textContent=a;out.innerHTML=`<div class="arch-state-trace">${values.map((v,i)=>`<div><span>t=${i+1}</span><strong>${number(v)}</strong><div class="arch-state-bar" style="--state-fill:${Math.min(100,v/2.5*100)}%" aria-hidden="true"></div></div>`).join('')}</div><p>${a<1?'旧脉冲逐渐衰减。':a===1?'状态保持；更多输入仍会累积。':'这个例子中旧脉冲不断放大，长期可能不稳定。'}</p>`;}
 document.querySelectorAll('.arch-budget-input').forEach(el=>on(el,'input',budget));
 ['query','mask-window','mask-k'].forEach(id=>on(q(`#arch-${id}`),'input',mask));
 document.querySelectorAll('.arch-delta-input').forEach(el=>on(el,'input',delta));on(q('#arch-ssm-a'),'input',ssm);
 budget();mask();delta();ssm();return ()=>controller.abort();
}
